INSERT INTO dealer_policies (topic, answer) VALUES
('hours','Open Monday to Saturday 10:00-18:00, closed Sunday. Test drives run on the hour, 10:00 to 17:00 (last slot 17:00).'),
('location','Apex Motors, 42 Demo Avenue, Gulberg, Lahore (fictional demo dealership). Free customer parking on site.'),
('warranty','Every used car includes a 90-day / 3,000-mile powertrain warranty. Extended protection plans of 1-3 years are available.'),
('returns','7-day / 300-mile money-back guarantee if the car is returned unmodified and undamaged.'),
('documents','Test drive: a valid driving licence. Financing: licence, proof of address and proof of income (recent payslips or bank statements).'),
('financing_partners','We work with several partner banks. APRs start from 5.9% depending on credit; our standard estimate uses 7.9%. Pre-qualification does not affect your credit score.'),
('trade_in_process','Get an online estimate, then a 20-minute inspection at the dealership, then a written offer valid for 7 days that can go straight toward your next car.'),
('test_drive_rules','Test drives last 30 minutes with a sales rep. You must be 18+ with a valid licence. One car per slot; bookings are free and can be cancelled anytime.')
